"husbandry/breed_an_animal\":\"The Parrots and the Bats\",\"husbandry/tame_an_animal\":\"Best Friends Forever\",\n  \"husbandry/plant_seed\":\"A Seedy Place\",\"husbandry/tactical_fishing\":\"Tactical Fishing\",\"husbandry/fishy_business\":\"Fishy Business\",\n  \"husbandry/bred_all_animals\":\"Two by Two\",\"husbandry/complete_catalogue\":\"A Complete Catalogue\",\"husbandry/balanced_diet\":\"A Balanced Diet\",\n  \"husbandry/obtain_netherite_hoe\":\"Serious Dedication\",\"husbandry/safely_harvest_honey\":\"Bee Our Guest\",\"husbandry/silk_touch_nest\":\"Total Beelocation\"\n};\n\n// The one advancement a Thunderless run is allowed to miss\nconst VVF = \"adventure/very_very_frightening\";\n\n// ---------- Multi-criteria advancements drawn as their own lines on the graph ----------\n// id → short name used in labels\nconst MULTI = {\n  \"adventure/adventuring_time\": \"AT\",\n  \"husbandry/balanced_diet\": \"ABD\",\n  \"adventure/kill_all_mobs\": \"MH\",\n  \"husbandry/bred_all_animals\": \"2x2\",\n  \"husbandry/complete_catalogue\": \"ACC\",\n};\n// How many criteria each needs (used for \"12/42\" while it's unfinished)\nconst REQ = {\n  \"adventure/adventuring_time\": 42,\n  \"husbandry/balanced_diet\": 39,\n  \"adventure/kill_all_mobs\": 33,\n  \"husbandry/bred_all_animals\": 19,\n  \"husbandry/complete_catalogue\": 11,\n};\n// Line colour for each (the colours themselves are defined in app.css as --s0 … --s5)\nconst MCOL = {\n  adv: \"var(--s0)\",\n  \"adventure/adventuring_time\": \"var(--s1)\",\n  \"husbandry/balanced_diet\": \"var(--s2)\",\n  \"adventure/kill_all_mobs\": \"var(--s3)\",\n  \"husbandry/bred_all_animals\": \"var(--s4)\",\n  \"husbandry/complete_catalogue\": \"var(--s5)\",\n};\n// Icon file (in the icons folder) for each\nconst MICON = {\n  \"adventure/adventuring_time\": \"boots\",\n  \"husbandry/balanced_diet\": \"m_abd\",\n  \"adventure/kill_all_mobs\": \"m_mh\",\n  \"husbandry/bred_all_animals\": \"m_2x2\",\n  \"husbandry/complete_catalogue\": \"m_acc\",\n};\n\n// ---------- Splits, in order. Names are shown on the site. ----------\n// How each split is detected lives in splits.js.\nconst SPLITS = [\n  {name: \"Any%\",         icon: \"dragon\"},\n  {name: \"Outer End\",    icon: \"chorus\"},\n  {name: \"Enchanting\",   icon: \"enchant\"},\n  {name: \"Midgame\",      icon: \"elytra\"},\n  {name: \"Debris\",       icon: \"debris\"},\n  {name: \"Endgame\",      icon: \"bucket\"},\n  {name: \"Post-endgame\", icon: null},      // icon comes from the run's last advancement (LAST_ICON below)\n];\n// Split colours (defined in app.css as --split0 … --split6)\nconst SCOL = SPLITS.map((_, i) => \"var(--split\" + i + \")\");\n\n// Which splits get a time card on the Stats page and a column in the runs table (numbers = position in SPLITS).\n// Any% and Outer End show when they ended; the others show when they started.\nconst SPLIT_CARDS = [0, 3, 5, 6];\n// Which splits appear under \"Fastest Splits\" on Overview\nconst FASTEST_SPLITS = [0, 1, 2, 3, 4, 5];\n// Extra splits shown after the splits: \"skulls\" or an advancement id (shows when it was completed)\nconst OTHER_SPLITS = [\"end/elytra\", \"skulls\", \"adventure/adventuring_time\", \"husbandry/complete_catalogue\"];\n\n// Post-endgame icon depends on the last advancement of the run\nconst LAST_ICON = {...MICON, \"adventure/throw_trident\": \"trident\", \"end/respawn_dragon\": \"dragon\", \"adventure/very_very_frightening\": \"trident\"};\nconst FALLBACK_LAST_ICON = \"star\";\n\n// ---------- Stats cards, in the order shown ----------\n// Stats page (\"Run stats\") and Overview (\"Average stats\") use the same list.\nconst STAT_CARDS = [\"deaths\", \"elytra\", \"skulls\", \"tntPerDebris\", \"shulkers\", \"creepers\"];\n\n// ---------- Rare Adventuring Time biome groups ----------\nconst RARE = [\n  {key: \"b_mushroom\",  name: \"Mushroom\",   members: [\"mushroom_fields\", \"mushroom_field_shore\"]},\n  {key: \"b_badlands\",  name: \"Badlands\",   members: [\"badlands\", \"badlands_plateau\", \"wooded_badlands_plateau\"]},\n  {key: \"b_jungle\",    name: \"Jungle\",     members: [\"jungle\", \"jungle_edge\", \"jungle_hills\", \"bamboo_jungle\", \"bamboo_jungle_hills\"]},\n  {key: \"b_snowy\",     name: \"Snowy\",      members: [\"snowy_tundra\", \"snowy_beach\", \"snowy_mountains\", \"snowy_taiga\", \"snowy_taiga_hills\"]},\n  {key: \"b_megataiga\", name: \"Mega Taiga\", members: [\"giant_tree_taiga\", \"giant_tree_taiga_hills\"]},\n];\n\n// Criterion names to shorten (as they'd otherwise appear → what to show)\nconst CRIT_RENAME = {\"British Shorthair\": \"British\", \"All Black\": \"Black\"};\n\n// ---------- Rules of thumb (times in milliseconds: 60000 = 1 minute) ----------\nconst RULES = {\n  campfireToHoney: 45 * 60000,     // a campfire starts (early) Endgame only if Bee Our Guest comes within this after it\n  postEndgameMin: 5 * 60000,        // a Post-endgame shorter than this is folded into Endgame\n  enchantPickupGap: 15 * 60000,     // enchanting-table pickups closer than this count as one enchanting session\n  debrisSessionGap: 10 * 60000,     // debris mined closer together than this counts as one debris session\n  skullIdleGap: 60000,              // skull split pauses after this long without a kill or skull\n  pickupAfterDeath: 2 * 60000,      // pickups this soon after a death are dropped items, not new ones\n  rareVisitGap: 10 * 60000,         // biome criteria closer than this count as one visit\n  riptideGap: 60000,                // trident uses closer than this count as one riptide session\n  riptideMinUses: 5,                // a session needs at least this many uses (single throws like A Throwaway Joke don't count)\n  riptideMinSpacing: 450,           // uses closer than this are counted once (a riptide can't be charged that fast)\n};\n\n/* ======== helpers.js ======== */\n/*\n * helpers.js — small tools used everywhere: formatting times and names, finding things on the page.\n */\n\n// Shortcut for finding an element on the page, e.g. $(\"#runsTable\")\nconst $ = s => document.querySelector(s);\n\n// Makes text safe to put inside HTML (so a note containing \"<\" can't break the page)\nconst esc = s => String(s).replace(/[&<>\"']/g, c => ({\"&\": \"&amp;\", \"<\": \"&lt;\", \">\": \"&gt;\", '\"': \"&quot;\", \"'\": \"&#39;\"}[c]));\n\n// 13901629 → \"3:51:41.629\" (dec = number of decimals on the seconds; 0 gives \"3:51:41\")\nconst fmt = (ms, dec = 3) => {\n  if (ms == null || isNaN(ms)) return \"—\";\n  const neg = ms < 0; ms = Math.abs(ms);\n  const h = Math.floor(ms / 3600000), m = Math.floor(ms % 3600000 / 60000), s = (ms % 60000) / 1000;\n  const ss = dec ? s.toFixed(dec).padStart(3 + dec, \"0\") : String(Math.floor(s)).padStart(2, \"0\");\n  return (neg ? \"-\" : \"\") + h + \":\" + String(m).padStart(2, \"0\") + \":\" + ss;\n};\n// Durations: 586000 → \"9:46\", 7380000 → \"2:03:00\"\nconst fmtShort = ms => {\n  if (ms == null || isNaN(ms)) return \"—\";\n  const t = Math.round(Math.abs(ms) / 1000), h = Math.floor(t / 3600), m = Math.floor(t % 3600 / 60), s = t % 60;\n  return (h ? h + \":\" + String(m).padStart(2, \"0\") : String(m)) + \":\" + String(s).padStart(2, \"0\");\n};\nconst num = n => n == null ? \"—\" : Number(n).toLocaleString();\nconst fmtDay = t => new Date(t).toLocaleDateString(undefined, {day: \"numeric\", month: \"short\", year: \"numeric\"});\n\n// Names\nconst titleCase = s => s.replace(/\\b[a-z]/g, c => c.toUpperCase());\nconst advName = id => ADV[id] || titleCase(id.split(\"/\").pop().replace(/_/g, \" \"));\nconst critName = c => {\n  const n = titleCase(String(c).replace(/^minecraft:/, \"\").split(\"/\").pop().replace(/\\.png$/, \"\").replace(/_/g, \" \"));\n  return CRIT_RENAME[n] || n;\n};\n\n// Groups sorted times into bursts: times closer than `gap` go in the same group\nfunction clusters(times, gap) {\n  const out = [];\n  for (const t of times) { const c = out[out.length - 1]; if (c && t - c[c.length - 1] <= gap) c.push(t); else out.push([t]); }\n  return out;\n}\n// Last point at or before time t in a list of [time, value] points\nconst lastBefore = (pts, t) => { let last = null; for (const p of pts) { if (p[0] <= t) last = p; else break; } return last; };\n\n/* ======== parse-log.js ======== */\n/*\n * parse-log.js — reads a Hermes play.log and keeps only what the site needs.\n * build.mjs uses this same file, so the site and the build always read logs the same way.\n *\n * A run looks like:\n *   events  – every advancement criterion: [igt, rta, advancement id, criterion, completed 1/0]\n *   dims    – dimension changes: [igt, \"o\" | \"n\" | \"e\"]\n *   deaths  – [igt, dimension, cause] (cause: see deathCause below)\n *   st      – timelines of stats (TNT used, debris mined, skulls picked up, gold blocks held, …)\n *   tot     – final totals (creepers killed, shulker boxes opened, …)\n *   clock   – [real time (ms), igt] several times a second, to line up other recordings (the ghost file) with the run.\n *             Only build.mjs uses it; it isn't stored.\n */\nfunction parseLog(text, filename) {\n  let start = null, player = null, uuid = null, seed = null, mc = null, dim = \"o\";   // seed: only if one was typed in\n  const seen = new Set(), done = new Set(), events = [], dims = [], deaths = [];\n  const st = {tnt: [], debris: [], skulls: [], ws: [], ench: [], trident: [], tridentUse: [], riptideUse: [], nautilus: [], drowned: [], tntHeld: [], campfire: [], hives: [], debrisGot: [], debrisTnt: [], wither: [], rose: [], gold: [], goldV: 2, rack: [], desert: [], gapple: null, gappleMax: 0};\n  const tot = {}, clock = [];\n  const inv = {}, skInv = {}; let inDesert = false, goldCum = 0, tntCum = 0, skOwed = 0, skHeld = [], dbHeld = 0, dbOwed = 0, rackNow = 0, lastTnt = null, ripHeld = 0, debrisPlaced = 0; const dbInv = {}, rackRecent = [], ripInv = {};   // skOwed: skulls dropped by dying, to be picked up again; skHeld: [time, skulls held] when it changes\n  let killedBy = null; const hits = [];   // for working out how each death happened\n  const TRACK = {\n    \"minecraft.used:minecraft.tnt\": \"tnt\", \"minecraft.mined:minecraft.ancient_debris\": \"debris\",\n    \"minecraft.picked_up:minecraft.wither_skeleton_skull\": \"skulls\", \"minecraft.killed:minecraft.wither_skeleton\": \"ws\",\n    \"minecraft.picked_up:minecraft.enchanting_table\": \"ench\",\n    \"minecraft.picked_up:minecraft.trident\": \"trident\", \"minecraft.used:minecraft.trident\": \"tridentUse\", \"minecraft.picked_up:minecraft.nautilus_shell\": \"nautilus\", \"minecraft.killed:minecraft.drowned\": \"drowned\", \"minecraft.used:minecraft.campfire\": \"campfire\",\n    \"minecraft.picked_up:minecraft.bee_nest\": \"hives\", \"minecraft.picked_up:minecraft.beehive\": \"hives\", \"minecraft.killed:minecraft.wither\": \"wither\", \"minecraft.picked_up:minecraft.wither_rose\": \"rose\"\n  };\n  const TOT = {\n    \"minecraft.killed:minecraft.creeper\": \"creepers\", \"minecraft.custom:minecraft.damage_taken\": \"damage\",\n    \"minecraft.custom:minecraft.open_shulker_box\": \"shulkerOpen\", \"minecraft.custom:minecraft.open_chest\": \"chests\",\n    \"minecraft.custom:minecraft.traded_with_villager\": \"trades\", \"minecraft.custom:minecraft.mob_kills\": \"mobKills\",\n    \"minecraft.used:minecraft.tnt\": \"tnt\", \"minecraft.mined:minecraft.ancient_debris\": \"debris\",\n    \"minecraft.picked_up:minecraft.wither_skeleton_skull\": \"skulls\", \"minecraft.killed:minecraft.wither_skeleton\": \"ws\",\n    \"minecraft.custom:minecraft.deaths\": \"deaths\", \"minecraft.custom:minecraft.jump\": \"jumps\"\n  };\n  for (const line of text.split(\"\\n\")) {\n    if (!line) continue;\n    // clock: real time and IGT from any kind of line (cheap: no JSON parsing), a few times a second\n    if (line.startsWith('{\"time\":')) {\n      const w = parseInt(line.slice(8), 10), ri = line.lastIndexOf('\"retime\":'), gi = ri > 0 ? ri + 3 : line.lastIndexOf('\"igt\":');\n      if (gi > 0 && (!clock.length || w - clock[clock.length - 1][0] >= 250)) clock.push([w, parseInt(line.slice(gi + 6), 10)]);\n    }\n    const q = line.indexOf('\"type\":\"'); if (q < 0) continue;\n    const type = line.slice(q + 8, line.indexOf('\"', q + 8));\n    // (inventory lines are only read for god apples and skulls: while skulls are held, every one, as any slot could lose one)\n    // (and for debris: while any is held, every one too)\n    if (type === \"inventory_slots\" && !line.includes(\"enchanted_golden_apple\") && !line.includes(\"null\") && !line.includes(\"wither_skeleton_skull\") && !(skHeld.length && skHeld[skHeld.length - 1][1] > 0)\n      && !line.includes(\"ancient_debris\") && !line.includes(\"netherite_scrap\") && !dbHeld && !line.includes(\"minecraft:riptide\") && !ripHeld) continue;\n    if (![\"advancement\",\"dimension\",\"initialize\",\"stat\",\"inside_structures\",\"inventory_slots\"].includes(type)) continue;\n    let e; try { e = JSON.parse(line); } catch { continue; }\n    if (start == null && e.time) start = e.time;\n    // (times are SpeedRunIGT's retimed IGT, the IGT rounded to game ticks, which is what runs are timed with; logs\n    // from before SpeedRunIGT had it use the IGT)\n    const igt = e.speedrunigt ? e.speedrunigt.retime ?? e.speedrunigt.igt : 0, rta = e.speedrunigt ? e.speedrunigt.rta : 0, d = e.data || {};\n    if (!player && d.player && d.player.name) { player = d.player.name; if (/^[0-9a-f-]{32,36}$/i.test(d.player.uuid || \"\")) uuid = d.player.uuid; }\n    if (type === \"initialize\") { mc = d.mc_version; if (e.time) start = e.time; if (d.entered_seed) seed = String(d.entered_seed); }\n    else if (type === \"dimension\") {\n      const x = String(d.dimension || \"\").replace(\"minecraft:\", \"\");\n      dim = x === \"the_nether\" ? \"n\" : x === \"the_end\" ? \"e\" : \"o\";\n      dims.push([igt, dim]);\n    } else if (type === \"advancement\") {\n      if (!d.id || d.id.startsWith(\"minecraft:recipes/\")) continue;\n      const id = d.id.replace(\"minecraft:\", \"\"), key = id + \"|\" + d.criterion_name;\n      if (seen.has(key)) continue;\n      seen.add(key); if (d.completed) done.add(id);\n      events.push([igt, rta, id, String(d.criterion_name).replace(/^minecraft:/, \"\"), d.completed ? 1 : 0]);\n    } else if (type === \"stat\") {\n      const k = d.stat, diff = Math.max(1, d.diff || 1);\n      let newDebris = k === \"minecraft.mined:minecraft.ancient_debris\" ? diff : 0;   // (less any that were placed and mined again)\n      if (TOT[k]) tot[TOT[k]] = d.value;\n      // (skulls dropped by dying and picked up again aren't new skulls)\n      if (k === \"minecraft.picked_up:minecraft.wither_skeleton_skull\" && skOwed > 0) { const again = Math.min(diff, skOwed); skOwed -= again; for (let i = again; i < diff; i++) st.skulls.push(igt); }\n      // (debris placed and mined again isn't new debris)\n      else if (k === \"minecraft.mined:minecraft.ancient_debris\" && debrisPlaced > 0) { const again = Math.min(diff, debrisPlaced); debrisPlaced -= again; newDebris = diff - again; for (let i = again; i < diff; i++) st.debris.push(igt); }\n      else if (TRACK[k]) for (let i = 0; i < diff; i++) st[TRACK[k]].push(igt);\n      if (k === \"minecraft.used:minecraft.ancient_debris\") debrisPlaced += diff;\n      if (k === \"minecraft.used:minecraft.trident\" && ripHeld) for (let i = 0; i < diff; i++) st.riptideUse.push(igt);\n      if (k === \"minecraft.custom:minecraft.damage_taken\") { hits.push([igt, d.diff || 0]); if (hits.length > 12) hits.shift(); }\n      if (k.startsWith(\"minecraft.killed_by:\")) killedBy = [igt, k.slice(k.indexOf(\":\") + 1).replace(/^minecraft\\./, \"\")];\n      if (k === \"minecraft.custom:minecraft.deaths\") { deaths.push([igt, dim, deathCause(igt, dim, killedBy, hits)]); killedBy = null; hits.length = 0; // (the slots are often emptied just before the death is logged: what was held in the seconds before)\n        skOwed += Math.max(0, ...skHeld.filter(h => h[0] >= igt - 5000).map(h => h[1]), skHeld.length ? skHeld[skHeld.length - 1][1] : 0);\n        for (const sl in skInv) skInv[sl] = 0; skHeld.push([igt, 0]); for (const sl in dbInv) dbInv[sl] = 0; dbOwed += dbHeld; dbHeld = 0; for (const sl in ripInv) ripInv[sl] = 0; ripHeld = 0; }\n      let g = 0;\n      if (k === \"minecraft.mined:minecraft.gold_block\" || k === \"minecraft.crafted:minecraft.gold_block\") g = diff;\n      else if (k === \"minecraft.used:minecraft.gold_block\") g = -diff;\n      else if (k === \"minecraft.crafted:minecraft.gold_ingot\" && diff % 9 === 0) g = -diff / 9;   // blocks broken down into ingots\n      if (g) { goldCum += g; st.gold.push([igt, goldCum]); }\n      let tg = 0;\n      if (k === \"minecraft.picked_up:minecraft.tnt\" || k === \"minecraft.crafted:minecraft.tnt\") { tg = diff; tot.tntGot = (tot.tntGot || 0) + diff; }\n      else if (k === \"minecraft.used:minecraft.tnt\") tg = -diff;\n      if (tg) { tntCum += tg; st.tntHeld.push([igt, tntCum]); }\n      // debris from TNT: TNT used in the 5 minutes before, and no more than a few netherrack mined in the 15 seconds before\n      // (checking around the blast); debris hit while mining netherrack non-stop (strip mining, digging the TNT tunnel) isn't\n      if (k === \"minecraft.used:minecraft.tnt\") lastTnt = igt;\n      if (k === \"minecraft.mined:minecraft.netherrack\") { rackNow = d.value; rackRecent.push([igt, rackNow]); while (rackRecent.length && rackRecent[0][0] < igt - 60000) rackRecent.shift(); }\n      if (k === \"minecraft.mined:minecraft.ancient_debris\" && lastTnt != null && igt - lastTnt <= 300000) {\n        const b = rackRecent.filter(p => p[0] <= igt - 15000).pop(), first = rackRecent.find(p => p[0] > igt - 15000);\n        const before = b ? b[1] : first ? first[1] - 1 : rackNow;   // (netherrack mined just before: the first in the 15 seconds counts too)\n        if (rackNow - before <= 20) for (let i = 0; i < newDebris; i++) st.debrisTnt.push(igt);\n      }\n      if (k === \"minecraft.mined:minecraft.netherrack\") {\n        const lr = st.rack[st.rack.length - 1];\n        if (lr && igt - lr[0] < 2000) lr[1] = d.value; else st.rack.push([igt, d.value]);\n      }\n      if (/^minecraft\\.used:minecraft\\.[a-z_]*shulker_box$/.test(k)) tot.shulkerPlaced = (tot.shulkerPlaced || 0) + diff;\n    } else if (type === \"inside_structures\") {\n      const now = (d.structures || []).includes(\"desert_pyramid\");\n      if (now && !inDesert) st.desert.push(igt);\n      inDesert = now;\n    } else if (type === \"inventory_slots\") {\n      for (const [slot, v] of Object.entries(d.slots || {})) { inv[slot] = v && v.id === \"minecraft:enchanted_golden_apple\" ? (v.Count || 1) : 0; skInv[slot] = v && v.id === \"minecraft:wither_skeleton_skull\" ? (v.Count || 1) : 0; }\n      // riptide tridents in the inventory (a trident use is only a riptide while one is held)\n      for (const [slot, v] of Object.entries(d.slots || {})) ripInv[slot] = v && v.id === \"minecraft:trident\" && ((v.tag && v.tag.Enchantments) || []).some(e => String(e.id) === \"minecraft:riptide\") ? 1 : 0;\n      ripHeld = Object.values(ripInv).reduce((a, b) => a + b, 0);\n      // debris (or scrap) turning up in the inventory in the Nether: mined, or from a chest (which the stats don't count)\n      for (const [slot, v] of Object.entries(d.slots || {})) dbInv[slot] = v && (v.id === \"minecraft:ancient_debris\" || v.id === \"minecraft:netherite_scrap\") ? (v.Count || 1) : 0;\n      const db = Object.values(dbInv).reduce((a, b) => a + b, 0);\n      if (db > dbHeld) { const again = Math.min(db - dbHeld, dbOwed); dbOwed -= again; if (db - dbHeld > again && dim === \"n\") st.debrisGot.push(igt); }   // (not what was dropped by dying)\n      dbHeld = db;\n      const sk = Object.values(skInv).reduce((a, b) => a + b, 0), prev = skHeld.length ? skHeld[skHeld.length - 1] : null;\n      if (!prev || prev[1] !== sk) { if (prev && sk < prev[1]) skHeld.push([igt, prev[1]]); skHeld.push([igt, sk]); }\n      const n = Object.values(inv).reduce((a, b) => a + b, 0);\n      if (n > 0 && st.gapple == null) st.gapple = igt;\n      st.gappleMax = Math.max(st.gappleMax, n);\n    }\n  }\n  tot.skulls = st.skulls.length; tot.debris = st.debris.length;   // (not the picked-up stat, which counts skulls picked up again after dying)\n  if (!events.length) throw new Error(filename + \" has no advancement events. Use the play.log from Hermes.\");\n  const comp = events.filter(e => e[4]);\n  const last = comp.length ? comp[comp.length - 1] : events[events.length - 1];\n  return {start: start || Date.now(), player: player || \"Unknown\", uuid, seed, mc: mc || \"\", finalIgt: last[0], finalRta: last[1],\n    critCount: seen.size, events, dims, deaths, st, tot, meta: {}, addedAt: Date.now(), clock};\n}\n\n/*\n * How a death happened. The log names the mob when a mob did it (\"killed_by\"); otherwise it's a best guess\n * from the damage taken just before (damage is in tenths of a heart-half, so 10 = half a heart):\n *   \"mob:<id>\"  killed by that mob\n *   \"fire\"      several hits of exactly 10 in a row (burning)\n *   \"void\"      several hits of 20–45 in a row, in the End (falling out of the world)\n *   \"lava\"      the same, anywhere else\n *   \"impact\"    one big hit (10+ damage): a fall or an explosion\n *   \"\"          can't tell\n * runs.json can say it better for any death (\"deathCauses\").\n */\nfunction deathCause(t, dim, killedBy, hits) {\n  if (killedBy && t - killedBy[0] < 1000) return \"mob:\" + killedBy[1];\n  const recent = hits.filter(h => t - h[0] < 6000).map(h => h[1]), tail = recent.slice(-3);\n  if (tail.length === 3 && tail.every(x => x === 10)) return \"fire\";\n  if (tail.length === 3 && tail.every(x => x >= 20 && x <= 45)) return dim === \"e\" ? \"void\" : \"lava\";\n  if (recent.length && recent[recent.length - 1] >= 100) return \"impact\";\n  return \"\";\n}\n\n// A stable id for a run (based on when the world was started)\nconst runKey = r => \"run-\" + r.start + \"-\" + String(r.player).replace(/[^A-Za-z0-9_-]/g, \"\");\n\n// Runs are stored with each event squashed into one \"igt|rta|id|criterion|done\" string to keep files small.\nconst encodeRun = r => { const {_d, clock, ...x} = r; return {...x, events: r.events.map(e => e.join(\"|\"))}; };\nconst decodeRun = x => ({meta: {}, st: {}, tot: {}, deaths: [], ...x,\n  events: (x.events || []).map(s => { if (Array.isArray(s)) return s; const p = String(s).split(\"|\"); return [+p[0], +p[1], p[2], p.slice(3, -1).join(\"|\"), +p[p.length - 1]]; }),\n  dims: (x.dims || []).map(s => Array.isArray(s) ? s : [+String(s).split(\"|\")[0], String(s).split(\"|\")[1]])});\n\n/* ======== runs.js ======== */\n/*\n * runs.js — loads the runs, icons and site text that build.mjs put into the page, and small questions about a run\n * (its number, date, title, video link…).\n */\nlet DATA = {runs: [], icons: {}};\ntry { DATA = JSON.parse(document.getElementById(\"aa-data\").textContent) || DATA; } catch {}\n// The site's own words from its site.json (build.mjs only lets through text that exists in text.js)\nif (DATA.text && typeof DATA.text === \"object\") for (const [k, v] of Object.entries(DATA.text)) if (typeof T[k] === \"string\" && typeof v === \"string\") T[k] = v;\nconst RUNS = (DATA.runs || []).map(decodeRun);\n// The world record (someone else's run, from the site's wr/ folder): shown next to the PB, never counted in this site's stats\nconst WR = DATA.wr && typeof DATA.wr === \"object\" ? decodeRun(DATA.wr) : null;\n// the records it beat (wr/archive/), each with a page of its own; and every record so far, fastest (the current one) first\nconst WRS = Array.isArray(DATA.wrs) ? DATA.wrs.filter(r => r && typeof r === \"object\").map(decodeRun) : [];\nconst WR_HISTORY = [...(WR ? [WR] : []), ...WRS].filter(r => r.finalIgt != null).sort((a, b) => a.finalIgt - b.finalIgt);\nconst ICONS = (DATA.icons && typeof DATA.icons === \"object\") ? DATA.icons : {};\n\n// ---------- Icons ----------\nconst okIcon = v => typeof v === \"string\" && (/^data:image\\/(png|webp|gif|jpeg);base64,[A-Za-z0-9+\\/=]+$/.test(v) || /^icons\\/[a-z0-9_]+\\.(png|webp|gif|jpe?g)$/i.test(v));\n// Icon as an <img> (size in pixels), or \"\" if there's no icon for that name\nconst ic = (key, size = 20) => okIcon(ICONS[key]) ? `<img class=\"ico\" src=\"${ICONS[key]}\" width=\"${size}\" height=\"${size}\" alt=\"\">` : \"\";\n// Icon inside a graph (SVG), or \"\"\nconst icAt = (key, x, y, size) => okIcon(ICONS[key]) ? `<image href=\"${ICONS[key]}\" x=\"${x}\" y=\"${y}\" width=\"${size}\" height=\"${size}\" style=\"image-rendering:pixelated\"/>` : \"\";\n\n// ---------- About a run ----------\nconst runNum = r => r.meta && r.meta.num ? r.meta.num : RUNS.slice().sort((a, b) => a.start - b.start).indexOf(r) + 1;\nconst isWr = r => !!(r && r.meta && r.meta.wr);\n// a run looked at on its own (read from files on the Compare page; only in this tab, never saved)\nlet VIEWED = null;\nconst isViewed = r => !!(r && r.meta && r.meta.viewed);\nconst runTitle = r => isViewed(r) ? r.meta.label : isWr(r) ? (r.meta.former ? T.wrFormerWord : T.wrWord) + (r.meta.runner ? \" · \" + r.meta.runner : \"\") : T.runWord + \" \" + runNum(r);\n// The run's final time: with milliseconds, unless it was typed into runs.json without them\nconst runTime = r => fmt(r.finalIgt, r.manual && r.finalIgt % 1000 === 0 ? 0 : 3);\nconst byNumber = () => RUNS.slice().sort((a, b) => runNum(a) - runNum(b));\nconst findRun = id => RUNS.find(r => r.id === id) || (WR && WR.id === id ? WR : undefined) || WRS.find(r => r.id === id) || (VIEWED && VIEWED.id === id ? VIEWED : undefined);\n\n// Date shown for a run: the date from runs.json, otherwise the day the run finished\nconst doneAt = r => r.start + (r.finalRta || 0);\n// (a run without a log and without a date has no date: \"—\")\nconst runDay = r => {\n  const m = r.meta && r.meta.date;\n  if (m && /^\\d{4}-\\d{2}-\\d{2}$/.test(m)) { const [y, mo, da] = m.split(\"-\").map(Number); return fmtDay(new Date(y, mo - 1, da).getTime()); }\n  return r.manual ? \"—\" : fmtDay(doneAt(r));\n};\nconst dayNumber = r => { const m = r.meta && r.meta.date; if (!m && r.manual) return 0; const d = m ? new Date(m + \"T12:00\") : new Date(doneAt(r)); return d.getFullYear() * 1e4 + (d.getMonth() + 1) * 100 + d.getDate(); };\n\n// Thunderful / Thunderless / Invalid label (\"\" when a run without a log doesn't say)\nconst catPill = (d, style = \"\") => d.category === \"Unknown\" ? \"\" : `<span class=\"cat ${d.category.toLowerCase()}\"${style ? ` style=\"${style}\"` : \"\"}>${esc(d.category)}</span>`;\n\nconst okUrl = u => typeof u === \"string\" && /^https?:\\/\\/[^\\s\"'<>]+$/i.test(u);\n// Screenshot: a link, or an image build.mjs copied next to the page\nconst shotUrl = r => { const s = r.meta && r.meta.screenshot; if (okUrl(s)) return s; return typeof s === \"string\" && /^[A-Za-z0-9_\\-./ ]+\\.(png|jpe?g|webp|gif)$/i.test(s) && !s.split(\"/\").includes(\"..\") ? encodeURI(s) : null; };\nconst shotLink = (r, big) => shotUrl(r)\n  ? `<a class=\"vlink${big ? \" big\" : \"\"}\" href=\"${esc(shotUrl(r))}\" target=\"_blank\" rel=\"noopener noreferrer\" aria-label=\"${esc(T.screenshot)}\" title=\"${esc(T.screenshot)}\"><svg width=\"${big ? 18 : 14}\" height=\"${big ? 18 : 14}\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><rect x=\"3\" y=\"6\" width=\"18\" height=\"14\" rx=\"2\"/><circle cx=\"12\" cy=\"13\" r=\"3.5\"/><path d=\"M8 6l1.5-2h5L16 6\"/></svg>${big ? esc(T.screenshot) : \"\"}</a>`\n  : \"\";\nconst videoLink = (r, big) => okUrl(r.meta && r.meta.video)\n  ? `<a class=\"vlink${big ? \" big\" : \"\"}\" href=\"${esc(r.meta.video)}\" target=\"_blank\" rel=\"noopener noreferrer\" aria-label=\"${esc(T.watchVideo)}\" title=\"${esc(T.watchVideo)}\"><svg width=\"${big ? 18 : 14}\" height=\"${big ? 18 : 14}\" viewBox=\"0 0 24 24\" fill=\"currentColor\" aria-hidden=\"true\"><path d=\"M8 5v14l11-7z\"/></svg>${big ? esc(T.video) : \"\"}</a>`\n  : \"\";\n\n/* ======== splits.js ======== */\n/*\n * splits.js — works out when each split of a run starts and ends.\n *\n *   Any%          start → dragon killed (\"Free the End\"; if that only came later, \"Remote Getaway\" instead)\n *   Outer End     → leaving the End after getting elytra (or finding an End City)\n *   Enchanting    → last enchanting-table pickup of the first pickup session after leaving the End\n *   Midgame       → debris starts (or Endgame starts early, see below)\n *   Debris        first netherrack mined after entering the Nether for the main debris session\n *                 → back in the Overworld after the last debris of that session; then any later Nether trip where\n *                 more debris was got (mined, or from a chest) is more Debris, paused in between\n *   Endgame       → Overworld after The End... Again..., or the end of the run\n *   Post-endgame  from there to the final advancement; only counted if it lasts at least RULES.postEndgameMin.\n *                 If How Did We Get Here was done before getting a god apple, it starts earlier: the next time\n *                 they go into the Nether. Debris during Post-endgame pauses it, as with Endgame.\n *\n * Early Endgame: placing a campfire (setting up bees) after Enchanting starts Endgame, if the honey is collected soon\n * after (pre-placed hives: Endgame starts at the honey instead). If that's before\n * debris, Endgame is paused while Debris happens and continues back in the Overworld.\n *\n * Each split can have more than one stretch (\"segs\"), which is how a paused Endgame (or Post-endgame) is stored.\n */\n\n// Time an advancement was completed, or null\nconst advTime = (run, id) => { const e = run.events.find(x => x[2] === id && x[4]); return e ? e[0] : null; };\n// First dimension change after time t into a dimension matching `pred`\nconst firstDimAfter = (run, t, pred) => { if (t == null) return null; const d = run.dims.find(x => x[0] > t && pred(x[1])); return d ? d[0] : null; };\n\nfunction findSplits(run, comp) {\n  const st = run.st || {};\n\n  // Any%\n  const kd = advTime(run, \"end/kill_dragon\"), gw = advTime(run, \"end/enter_end_gateway\");\n  const anyUsesGateway = kd == null || (gw != null && kd > gw);\n  const anyEnd = anyUsesGateway ? gw : kd;\n\n  // Outer End: leave the End after the elytra\n  const lootDone = advTime(run, \"end/elytra\") ?? advTime(run, \"end/find_end_city\");\n  let outerEnd = null;\n  if (lootDone != null) { const i = run.dims.findIndex(x => x[0] > lootDone && x[1] !== \"e\"); if (i >= 0) outerEnd = run.dims[i][0]; }\n\n  // Enchanting: first session of enchanting-table pickups after leaving the End\n  const pickups = (st.ench || []).filter(t => t > (outerEnd ?? anyEnd ?? 0));\n  const session = pickups.length ? clusters(pickups, RULES.enchantPickupGap)[0] : null;\n  const enchDone = session ? session[session.length - 1] : null;\n\n  // Debris: the biggest burst of debris mining\n  const debrisSession = (st.debris || []).length ? clusters(st.debris, RULES.debrisSessionGap).sort((a, b) => b.length - a.length)[0] : null;\n  let debrisStart = null, debrisEnd = null;\n  if (debrisSession) {\n    const d0 = debrisSession[0];\n    const netherIn = run.dims.filter(x => x[0] <= d0 && x[1] === \"n\").pop();\n    const nIn = netherIn && (enchDone == null || netherIn[0] >= enchDone) ? netherIn[0] : null;\n    const firstRack = nIn != null ? (st.rack || []).find(p => p[0] >= nIn && p[0] <= d0) : null;\n    debrisStart = firstRack ? firstRack[0] : nIn != null ? nIn : d0;\n    debrisEnd = firstDimAfter(run, debrisSession[debrisSession.length - 1], x => x === \"o\");\n  }\n  // more debris later on (more netherite needed): each Nether trip after that where debris was mined or turned up in the\n  // inventory (from a chest) is more Debris, with what's between paused\n  const moreDebris = [];\n  if (debrisEnd != null) run.dims.forEach((x, i) => {\n    if (x[1] !== \"n\" || x[0] < debrisEnd) return;\n    const out = i + 1 < run.dims.length ? run.dims[i + 1][0] : run.finalIgt;\n    if ([...(st.debris || []), ...(st.debrisGot || [])].some(t => t >= x[0] && t <= out)) moreDebris.push([x[0], out]);\n  });\n  const debrisSegs = debrisStart != null && debrisEnd != null ? [[debrisStart, debrisEnd], ...moreDebris] : [];\n\n  // Post-endgame: back in the Overworld after The End... Again...\n  const endAgain = advTime(run, \"end/respawn_dragon\");\n  let postStart = firstDimAfter(run, endAgain, x => x === \"o\");\n  // ...or, when How Did We Get Here was done before they had a god apple, the next time they go into the Nether\n  const hdwgh = advTime(run, \"nether/all_effects\");\n  const eaten = run.events.find(x => x[2] === \"husbandry/balanced_diet\" && x[3] === \"enchanted_golden_apple\");\n  const godApple = Math.min(st.gapple ?? Infinity, eaten ? eaten[0] : Infinity);\n  if (hdwgh != null && hdwgh > (enchDone ?? Infinity) && !(godApple <= hdwgh)) {\n    const trip = firstDimAfter(run, hdwgh, x => x === \"n\");\n    if (trip != null && (postStart == null || trip < postStart)) postStart = trip;\n  }\n  if (postStart != null && run.finalIgt - postStart < RULES.postEndgameMin) postStart = null;\n\n  // Early Endgame (campfire placed before debris, or no Debris split). Only a campfire that's used for honey soon after\n  // counts (Bee Our Guest within RULES.campfireToHoney): hives set up long before, e.g. while passing 0,0 in Midgame,\n  // don't start Endgame; then it starts when the honey is collected.\n  const honey = advTime(run, \"husbandry/safely_harvest_honey\");\n  const camps = (st.campfire || []).filter(t => t > (enchDone ?? Infinity));\n  let campT = honey == null ? camps[0] : camps.find(t => t <= honey && honey - t <= RULES.campfireToHoney);\n  if (campT == null && honey != null && camps.some(t => t <= honey)) campT = honey;\n  const earlyEnd = campT != null && (debrisStart == null || campT < debrisStart);\n  const endgameEnd = postStart ?? run.finalIgt;\n\n  const seg = (a, b) => a != null && b != null && b >= a ? [[a, b]] : [];\n  // a stretch with Debris taken out of it (Endgame and Post-endgame pause for it)\n  const noDebris = (a, b) => {\n    if (a == null || b == null || b < a) return [];\n    let out = [[a, b]];\n    for (const [ds, de] of debrisSegs) out = out.flatMap(([x, y]) => de <= x || ds >= y ? [[x, y]] : [...(ds > x ? [[x, ds]] : []), ...(de < y ? [[de, y]] : [])]);\n    return out;\n  };\n  const segsBySplit = [\n    seg(0, anyEnd),\n    seg(anyEnd, outerEnd),\n    seg(outerEnd, enchDone),\n    seg(enchDone, [earlyEnd ? campT : debrisStart, postStart].filter(t => t != null).reduce((a, t) => a == null ? t : Math.min(a, t), null)),\n    debrisSegs,\n    noDebris(earlyEnd ? campT : debrisEnd, endgameEnd),\n    postStart != null ? noDebris(postStart, run.finalIgt) : [],\n  ];\n\n  const lastId = (comp[comp.length - 1] || [])[2];\n  const postIcon = LAST_ICON[lastId] && okIcon(ICONS[LAST_ICON[lastId]]) ? LAST_ICON[lastId] : FALLBACK_LAST_ICON;\n\n  const splits = SPLITS.map((p, i) => {\n    const segs = segsBySplit[i], ok = segs.length > 0;\n    return {\n      name: p.name,\n      icon: p.icon || postIcon,\n      segs,\n      start: ok ? segs[0][0] : null,\n      end: ok ? segs[segs.length - 1][1] : null,\n      dur: ok ? segs.reduce((a, g) => a + g[1] - g[0], 0) : null,\n    };\n  });\n  return {splits, anyEnd, endAgain};\n}\n\n// The time shown for a split: Any% and Outer End show when they ended, the rest when they started\nconst splitMark = (p, i) => i <= 1 ? p.end : p.start;\n\n/* ======== stats.js ======== */\n/*\n * stats.js — everything the site calculates about a run. derive(run) does it once per run and remembers it.\n *\n * What derive() returns:\n *   category     \"Thunderful\" (80/80), \"Thunderless\" (79/80, only Very Very Frightening missing) or \"Invalid\";\n *                runs without a log use \"hundred\" from runs.json, or \"Unknown\"\n *   splits       see splits.js\n *   deaths       [{t, dim, intentional, i, cause}]  (deaths after The End... Again... count as intentional unless runs.json\n *                says otherwise; cause is the text for how it happened, from the log or runs.json's \"deathCauses\")\n *   multis       progress of each multi-criteria advancement\n *   skullRate    skulls picked up, and wither skeletons killed up to the last skull (Any% kills don't count)\n *   skullSplit   time spent actively farming skulls (see findSkullSplit)\n *   tntPer       TNT placed per debris mined during the Debris split\n *   lanes        times you got tridents, skulls and nautilus shells\n *   rare         rare biome groups (see findRareBiomes)\n *   gold         gold block estimate over time\n *   thunder      when Very Very Frightening was earned (the logs don't record weather), or null\n *   riptide      riptide sessions: [{start, end, uses}] (see findRiptide)\n */\nfunction derive(run) {\n  if (run._d) return run._d;\n  if (run.manual) return run._d = deriveManual(run);\n  const st = run.st || {};\n  const comp = run.events.filter(e => e[4]);                    // completed advancements\n  const doneSet = new Set(comp.map(e => e[2]));\n  const missing = Object.keys(ADV).filter(k => !doneSet.has(k));\n  const category = !missing.length ? \"Thunderful\" : missing.length === 1 && missing[0] === VVF ? \"Thunderless\" : \"Invalid\";\n\n  const {splits, anyEnd, endAgain} = findSplits(run, comp);\n\n  // Deaths: runs.json can mark any death as intentional or not (\"intent\"); otherwise deaths after\n  // The End... Again... are intentional and everything else isn't.\n  const intent = (run.meta && run.meta.intent) || {}, causes = (run.meta && run.meta.deathCauses) || {};\n  const deaths = (run.deaths || []).map((d, i) => ({t: d[0], dim: d[1], i,\n    intentional: intent[i] != null ? !!intent[i] : endAgain != null && d[0] >= endAgain,\n    cause: causes[i] || T.deathCause(d[2] || \"\")}));\n\n  // Multi-criteria advancements\n  const multis = Object.keys(MULTI).map(id => {\n    const xs = run.events.filter(e => e[2] === id); if (!xs.length) return null;\n    const dn = xs.find(e => e[4]);\n    return {id, tot: dn ? xs.length : REQ[id], first: xs[0][0], done: dn ? dn[0] : null, last: xs[xs.length - 1][3], xs};\n  }).filter(Boolean);\n\n  // Pickups right after a death are the dropped items being collected again, so they're skipped\n  const deathT = (run.deaths || []).map(x => x[0]);\n  const obtains = key => (st[key] || []).filter(t => !deathT.some(dt => t >= dt && t - dt < RULES.pickupAfterDeath));\n\n  // Skulls\n  const skulls = st.skulls || [];\n  const ws = (st.ws || []).filter(t => anyEnd == null || t > anyEnd);   // wither skeletons killed during Any% don't count\n  const lastSkull = skulls.length ? skulls[skulls.length - 1] : null;\n  const skullRate = {skulls: skulls.length, kills: lastSkull != null ? ws.filter(t => t <= lastSkull).length : ws.length};\n\n  // TNT per debris, counted inside the Debris split only, and only the debris that came from TNT (st.debrisTnt: TNT used\n  // just before, and only a few netherrack mined in the seconds before), not what was found mining netherrack\n  const debrisSplit = splits[4];\n  const inDebris = arr => (arr || []).filter(t => debrisSplit.segs.some(g => t >= g[0] && t <= g[1]));\n  const fromTnt = st.debrisTnt || st.debris;\n  const tntD = inDebris(st.tnt).length, debD = inDebris(fromTnt).length;\n\n  return run._d = {\n    comp, missing, category, splits, deaths, multis, skullRate, debrisSplit, tntD, debD,\n    tntPer: debD ? tntD / debD : null,\n    gold: st.goldV === 2 ? (st.gold || []) : [],\n    lanes: {trident: obtains(\"trident\"), skull: obtains(\"skulls\"), nautilus: obtains(\"nautilus\")},\n    skullSplit: findSkullSplit(run, ws, obtains(\"skulls\")),\n    rare: findRareBiomes(run),\n    thunder: (comp.find(e => e[2] === VVF) || [null])[0],\n    riptide: findRiptide(run),\n  };\n}\n\n/*\n * Riptide: bursts of trident uses. A riptide trident can be used again right away, while a thrown one\n * has to be picked up first, so throws (A Throwaway Joke, Very Very Frightening) never make a burst.\n */\nfunction findRiptide(run) {\n  const uses = [];\n  // (only uses while a riptide trident was in the inventory, so throwing a plain one again and again isn't riptide)\n  const st = run.st || {};\n  for (const t of (st.riptideUse || st.tridentUse || [])) if (!uses.length || t - uses[uses.length - 1] >= RULES.riptideMinSpacing) uses.push(t);\n  return clusters(uses, RULES.riptideGap).filter(c => c.length >= RULES.riptideMinUses)\n    .map(c => ({start: c[0], end: c[c.length - 1], uses: c.length}));\n}\n\n/*\n * Skull split: starts at the first Nether visit with at least 3 wither skeleton kills (or a skull) and ends\n * at the 3rd skull. Only active farming counts: it pauses after RULES.skullIdleGap without a kill or skull,\n * on any dimension change, and on a death.\n */\nfunction findSkullSplit(run, ws, skullsGot) {\n  if (!skullsGot.length || !ws.length) return null;\n  const endS = skullsGot[Math.min(2, skullsGot.length - 1)];\n  const nether = [];\n  run.dims.forEach((x, i) => { if (x[1] === \"n\") nether.push([x[0], i + 1 < run.dims.length ? run.dims[i + 1][0] : run.finalIgt]); });\n  const kills = ws.filter(t => t <= endS);\n  let startT = null;\n  for (const iv of nether) {\n    const k = kills.filter(t => t >= iv[0] && t <= iv[1]).length, sk = skullsGot.some(t => t >= iv[0] && t <= iv[1] && t <= endS);\n    if (k >= 3 || sk) { startT = Math.min(kills.find(t => t >= iv[0] && t <= iv[1]) ?? Infinity, skullsGot.find(t => t >= iv[0]) ?? Infinity); break; }\n  }\n  if (startT == null || !isFinite(startT)) startT = kills[0] ?? skullsGot[0];\n  const evs = [...kills, ...skullsGot.filter(t => t <= endS)].filter(t => t >= startT).sort((a, b) => a - b);\n  const breaks = [...run.dims.map(x => x[0]), ...(run.deaths || []).map(x => x[0])];\n  const segs = [];\n  evs.forEach(t => {\n    const g = segs[segs.length - 1];\n    if (g && t - g[1] <= RULES.skullIdleGap && !breaks.some(bk => bk > g[1] && bk <= t)) g[1] = t; else segs.push([t, t]);\n  });\n  return {segs, dur: segs.reduce((a, g) => a + (g[1] - g[0]), 0), start: startT, end: endS};\n}\n\n/*\n * Rare biomes: each group's Adventuring Time criteria are split into visits (bursts of criteria).\n * A group is done when all its biomes have been visited.\n */\nfunction findRareBiomes(run) {\n  const atEv = run.events.filter(e => e[2] === \"adventure/adventuring_time\");\n  return RARE.map(g => {\n    const evs = atEv.filter(e => g.members.includes(e[3]));\n    const have = new Set();\n    const visits = clusters(evs.map(e => e[0]), RULES.rareVisitGap).map(ts => {\n      const crit = evs.filter(e => ts.includes(e[0])).map(e => e[3]); crit.forEach(c => have.add(c));\n      return {t: ts[0], tEnd: ts[ts.length - 1], crit, complete: g.members.every(m => have.has(m)), missing: g.members.filter(m => !have.has(m))};\n    });\n    const doneV = visits.find(v => v.complete);\n    return {...g, visits, done: doneV ? doneV.tEnd : null, first: evs.length ? evs[0][0] : null, missing: g.members.filter(m => !have.has(m))};\n  });\n}\n\n// A run with no log: just what runs.json says (time, 100%, splits). Everything else is empty.\nfunction deriveManual(run) {\n  const meta = run.meta || {}, marks = meta.splits || {};\n  const category = meta.hundred === true ? \"Thunderful\" : meta.hundred === false ? \"Thunderless\" : \"Unknown\";\n  // Any% (and Outer End) are shown by when they ended, the others by when they started (see splitMark)\n  const splits = SPLITS.map((p, i) => {\n    const t = marks[i] ?? null;\n    return {name: p.name, icon: p.icon, segs: [], dur: null, start: i <= 1 ? (t != null ? 0 : null) : t, end: i <= 1 ? t : null};\n  });\n  return {comp: [], missing: [], category, splits, deaths: [], multis: [], skullRate: {skulls: 0, kills: 0}, debrisSplit: splits[4],\n    tntD: 0, debD: 0, tntPer: null, gold: [], lanes: {trident: [], skull: [], nautilus: []}, skullSplit: null, rare: [], thunder: null, riptide: []};\n}\n\n// ---------- Across all runs ----------\nconst hasLog = r => !r.manual;\nconst logRuns = () => RUNS.filter(hasLog);\nconst isValid = r => derive(r).category !== \"Invalid\" && r.finalIgt != null;\nconst validRuns = () => RUNS.filter(isValid);\nconst pbRun = () => validRuns().sort((a, b) => a.finalIgt - b.finalIgt)[0] || null;\n// \"Missing A, B, C and 4 more\": the advancements an Invalid run didn't get\nconst missingText = (d, max = 5) => {\n  const names = d.missing.map(advName);\n  return T.invalidRunMissing + \" \" + names.slice(0, max).join(\", \") + (names.length > max ? \" \" + T.andMore(names.length - max) : \"\");\n};\nconst nonIntentionalDeaths = r => derive(r).deaths.filter(d => !d.intentional).length;\nconst average = xs => { xs = xs.filter(x => x != null && !isNaN(x)); return xs.length ? xs.reduce((a, b) => a + b, 0) / xs.length : null; };\n// Fastest value of f(run) among valid runs: {v, r}\nfunction fastest(f) { let b = null; validRuns().forEach(r => { const v = f(r); if (v != null && (b == null || v < b.v)) b = {v, r}; }); return b || {}; }\nfunction slowest(f) { let b = null; validRuns().forEach(r => { const v = f(r); if (v != null && (b == null || v > b.v)) b = {v, r}; }); return b || {}; }\n// the run closest to the average (what clicking \"avg\" opens)\nfunction nearest(f, avg) { let b = null; if (avg == null) return {}; validRuns().forEach(r => { const v = f(r); if (v != null && (b == null || Math.abs(v - avg) < Math.abs(b.v - avg))) b = {v, r}; }); return b || {}; }\n";
const PAGE = "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>AA Live</title>\n<style>\n@font-face{font-family:\"Minecraft\";src:url(data:font/otf;base64,) format(\"opentype\");font-weight:400 500}\n@font-face{font-family:\"Minecraft\";src:url(data:font/otf;base64,) format(\"opentype\");font-weight:600 800}\n:root{\n  --bg-alpha:0; --row:#16181e; --row-on:#24324a; --line:#262a33; --on:#1f5fd6;\n  --text:#e9ecf1; --dim:#8a92a3; --faint:#5b6273;\n  --ahead:#4cd07d; --behind:#ef5b5b; --gold:#f5c542; --blue:#6aa8ff;\n}\n*{box-sizing:border-box;border-radius:0}\nbutton{-webkit-appearance:none;appearance:none}\nhtml,body{margin:0}\nhtml,body{background:transparent}\nhtml.browser{background:#000}\nbody{text-shadow:2px 2px 0 #000;color:var(--text);font-family:\"Minecraft\",ui-monospace,monospace;font-size:16px;line-height:1.25;-webkit-font-smoothing:none}\n.split{margin:0}\n.box{background:rgba(0,0,0,var(--bg-alpha));overflow:hidden}\n.head{display:flex;align-items:center;gap:8px;padding:10px 12px 8px;border-bottom:2px solid var(--line)}\n.head .t{font-weight:700;font-size:17px;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.head .num{flex:1;color:var(--dim);font-size:14px;white-space:nowrap}\n.vs{border:0;background:var(--row);color:var(--text);font:inherit;font-size:13px;padding:4px 8px;cursor:pointer;white-space:nowrap}\n.vs:hover{background:var(--row-on)}\n.vs b{color:var(--dim);font-weight:400}\n.rows{padding:4px 0}\n.r{display:grid;grid-template-columns:22px 1fr auto 76px;align-items:center;gap:8px;padding:5px 12px;min-height:32px}\n.r.on{background:var(--on);color:#fff}\n.r.on .d.behind{color:#ffc2c2}\n.r img{width:20px;height:20px;image-rendering:pixelated}\n.r .n{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.r .d{text-align:right;min-width:58px}\n.r .tm{text-align:right}\n.r.todo .n,.r.todo .tm{color:var(--dim)}\n.r.wait .n{color:var(--text)}\n.ahead{color:var(--ahead)} .behind{color:var(--behind)} .gold{color:var(--gold)}\n.detail{display:flex;align-items:flex-end;gap:10px;padding:10px 12px 2px}\n.dl{flex:1;min-width:0;display:grid;gap:3px}\n.dn{display:flex;align-items:center;gap:8px;font-weight:700;white-space:nowrap;overflow:hidden}\n.dn img{width:32px;height:32px;image-rendering:pixelated;flex:none}\n.dn span{overflow:hidden;text-overflow:ellipsis}\n.dc{color:var(--dim);font-size:13px;white-space:nowrap}\n.dc b{color:var(--text);font-weight:400}\n.dr{text-align:right;white-space:nowrap}\n.big{font-size:44px;font-weight:700;line-height:1;letter-spacing:1px;text-shadow:3px 3px 0 #000;font-variant-numeric:tabular-nums}\n.big .ms{font-size:26px}\n.big.paused{color:var(--dim)}\n.seg{color:var(--dim);font-size:20px;margin-top:4px;text-shadow:2px 2px 0 #000}\n.seg .ms{font-size:14px}\n.info{border-top:2px solid var(--line);margin-top:8px;padding:6px 12px 8px}\n.kv{display:flex;justify-content:space-between;gap:12px;padding:2px 0;font-size:14px}\n.kv span:first-child{color:var(--dim)}\n.status{font-size:12px;color:var(--dim);white-space:nowrap}\n.status.live{color:var(--ahead)}\n.note{color:var(--dim);font-size:13px;padding:10px 12px;border-top:2px solid var(--line)}\n.hide{display:none}\n</style>\n</head>\n<body>\n<div class=\"split\">\n  <div class=\"box\">\n    <div class=\"head\"><span class=\"t\" id=\"title\">AA Live</span><span class=\"num\" id=\"num\"></span><span class=\"status\" id=\"status\"></span><button class=\"vs\" id=\"vs\" title=\"Change what you're compared with\"></button></div>\n    <div class=\"rows\" id=\"rows\"></div>\n    <div class=\"detail\">\n      <div class=\"dl\"><div class=\"dn\"><img id=\"segIcon\" alt=\"\"><span id=\"segName\"></span></div><div class=\"dc\" id=\"segComp\"></div><div class=\"dc\" id=\"segBest\"></div></div>\n      <div class=\"dr\"><div class=\"big\" id=\"timer\">0:00:00<span class=\"ms\">.000</span></div><div class=\"seg\" id=\"segTimer\"></div></div>\n    </div>\n    <div class=\"info\" id=\"info\"></div>\n    <div class=\"note hide\" id=\"note\"></div>\n  </div>\n</div>\n<script>\n\"use strict\";\nconst $ = id => document.getElementById(id);\nconst P = new URLSearchParams(location.search);\n// the background: see-through by default (for OBS); ?bg=0 to 100 makes it that much black\nconst bg = Math.min(100, Math.max(0, Number(P.get(\"bg\")) || 0));\ndocument.documentElement.style.setProperty(\"--bg-alpha\", bg / 100);\n// (in a normal browser tab there's nothing behind the page, so it's black there)\nif (!window.obsstudio) document.documentElement.classList.add(\"browser\");\nconst ORDER = [\"pb\", \"avg\", \"best\", \"worst\", \"wr\"];\nconst store = {get: k => { try { return localStorage.getItem(k); } catch { return null; } }, set: (k, v) => { try { localStorage.setItem(k, v); } catch {} }};\nlet comp = P.get(\"comp\") || store.get(\"aa-live-comp\") || \"pb\";\nlet S = null, connected = false;\n\nconst esc = s => String(s).replace(/[&<>\"]/g, c => ({\"&\": \"&amp;\", \"<\": \"&lt;\", \">\": \"&gt;\", '\"': \"&quot;\"}[c]));\n// 1:02:03, or 2:03 under an hour\nconst fmt = (ms, long) => { if (ms == null) return \"—\"; const s = Math.floor(Math.max(0, ms) / 1000), h = Math.floor(s / 3600), m = Math.floor(s / 60) % 60, x = String(s % 60).padStart(2, \"0\"); return h || long ? `${h}:${String(m).padStart(2, \"0\")}:${x}` : `${m}:${x}`; };\n// the same with milliseconds, smaller\n// (?ms=0 hides the milliseconds)\nconst showMs = P.get(\"ms\") !== \"0\";\nconst fmtMs = (ms, long) => fmt(ms, long) + (showMs ? `<span class=\"ms\">.${String(Math.floor(Math.max(0, ms)) % 1000).padStart(3, \"0\")}</span>` : \"\");\nconst delta = ms => (ms < 0 ? \"−\" : \"+\") + fmt(Math.abs(ms));\nconst cls = (ms, gold) => gold ? \"gold\" : ms <= 0 ? \"ahead\" : \"behind\";\n\nconst es = new EventSource(\"/events\");\nes.onmessage = e => { S = JSON.parse(e.data); connected = true; render(); };\nes.onerror = () => { connected = false; render(); };\n\n$(\"vs\").onclick = () => {\n  if (!S) return;\n  const have = ORDER.filter(k => S.comps[k]);\n  comp = have[(have.indexOf(comp) + 1) % have.length] || \"pb\";\n  store.set(\"aa-live-comp\", comp);\n  render();\n};\n\n// The IGT right now: from the latest line of the log, plus the time since then while the game is running\n// (it never goes back while running: a new line from the game can be a few milliseconds behind the count)\nlet shown = 0;\nfunction liveIgt() {\n  if (!S) return 0;\n  if (S.done || !S.anchor || !S.open || S.paused) return shown = S.igt;\n  const t = Math.max(S.igt, S.anchor.igt + (Date.now() - S.anchor.wall));\n  return shown = t < shown && shown - t < 2000 ? shown : t;\n}\n// (only touches the page when something changed)\nconst put = (el, html) => { if (el._h !== html) { el._h = html; el.innerHTML = html; } };\n\nfunction render() {\n  if (!S) { $(\"status\").textContent = connected ? \"\" : \"Not connected\"; return; }\n  const C = S.comps[comp] || S.comps[ORDER.find(k => S.comps[k])] || null, best = S.comps.best;\n  const now = liveIgt(), running = S.open && !S.paused && !S.done;\n  $(\"title\").textContent = S.title;\n  $(\"num\").textContent = S.num ? \"Run \" + S.num : \"\";\n  put($(\"vs\"), C ? `<b>vs</b> ${esc(C.short)}` : \"No runs\");\n  $(\"status\").textContent = !connected ? \"Not connected\" : S.done ? (S.thunderless ? \"Done · Thunderless\" : \"Done\") : !S.world ? \"Waiting for Minecraft\" : !S.file ? \"No Hermes log\" : !S.open ? \"World closed\" : S.paused ? \"Paused\" : \"Live\";\n  $(\"status\").className = \"status\" + (running && connected ? \" live\" : \"\");\n\n  const rows = S.splits.map((r, i) => ({...r, i, cur: r.dur + (r.from != null ? Math.max(0, now - r.from) : 0)}));\n  const ri = rows.findIndex(r => r.from != null);\n  rows.forEach(r => { r.fin = S.done ? r.has : r.has && r.from == null && ri >= 0 && r.i < ri; r.on = r.i === ri; });\n  const c = i => C && C.splits[i] != null ? C.splits[i] : null, b = i => best && best.splits[i] != null ? best.splits[i] : null;\n\n  // (the rows are made once and then only changed, so the icons don't flicker)\n  const box = $(\"rows\");\n  while (box.children.length < rows.length) box.insertAdjacentHTML(\"beforeend\", `<div class=\"r\"><img alt=\"\"><span class=\"n\"></span><span class=\"d\"></span><span class=\"tm\"></span></div>`);\n  while (box.children.length > rows.length) box.lastChild.remove();\n  rows.forEach((r, k) => {\n    let d = \"\", dc = \"\";\n    if (r.fin && c(r.i) != null) { const g = b(r.i) != null && r.cur < b(r.i); d = delta(r.cur - c(r.i)); dc = cls(r.cur - c(r.i), g); }\n    else if (r.on && c(r.i) != null && r.cur > c(r.i)) { d = delta(r.cur - c(r.i)); dc = \"behind\"; }\n    const shown = r.fin || r.on || r.has, el = box.children[k], [img, n, de, tm] = el.children;\n    const src = S.icons[r.icon] || \"\";\n    if (img.getAttribute(\"src\") !== src) { if (src) img.setAttribute(\"src\", src); else img.removeAttribute(\"src\"); }\n    img.style.visibility = src ? \"\" : \"hidden\";\n    el.className = \"r\" + (r.on ? \" on\" : \"\") + (shown ? \"\" : \" todo\") + (r.has && !r.fin && !r.on ? \" wait\" : \"\");\n    n.textContent = r.name; de.textContent = d; de.className = \"d \" + dc; tm.textContent = fmt(shown ? r.cur : c(r.i));\n  });\n\n  // what's left, going by the comparison (pace) and by the best segments (best possible time)\n  const left = f => rows.filter(r => !r.fin).reduce((a, r) => a + Math.max(0, (f(r.i) ?? 0) - r.cur), 0);\n  const pace = C ? now + left(c) : null, possible = best ? now + left(b) : null;\n  const pb = S.comps.pb;\n  const t = $(\"timer\");\n  put(t, fmtMs(now, true));\n  t.className = \"big\" + (S.done ? (pb && now < pb.final ? \" gold\" : C && C.final != null ? \" \" + cls(now - C.final) : \"\") : !running ? \" paused\" : C && C.final != null ? \" \" + cls(pace - C.final) : \"\");\n  // the split it's on: its icon and name, its time, and the comparison's and best time for it\n  const on = rows[ri], icon = on && S.icons[on.icon] || \"\", si = $(\"segIcon\");\n  if (si.getAttribute(\"src\") !== icon) { if (icon) si.setAttribute(\"src\", icon); else si.removeAttribute(\"src\"); }\n  si.style.display = icon ? \"\" : \"none\";\n  $(\"segName\").textContent = on ? on.name : \"\";\n  put($(\"segTimer\"), on ? fmtMs(on.cur) : \"\");\n  put($(\"segComp\"), on && C && c(on.i) != null ? `${esc(C.short)}: <b>${fmt(c(on.i))}</b>` : \"\");\n  put($(\"segBest\"), on && b(on.i) != null ? `Best: <b>${fmt(b(on.i))}</b>` : \"\");\n\n  const fins = rows.filter(r => r.fin), prev = fins[fins.length - 1];\n  const kv = (k, v, cl = \"\") => `<div class=\"kv\"><span>${k}</span><span class=\"${cl}\">${v}</span></div>`;\n  let info = \"\";\n  if (prev && c(prev.i) != null) info += kv(\"Previous segment\", delta(prev.cur - c(prev.i)), cls(prev.cur - c(prev.i), b(prev.i) != null && prev.cur < b(prev.i)));\n  if (C && C.final != null && !S.done) info += kv(`Pace (vs ${esc(C.short)})`, fmt(pace, true) + ` <span class=\"${cls(pace - C.final)}\">${delta(pace - C.final)}</span>`);\n  if (possible != null && !S.done) info += kv(\"Best possible time\", fmt(possible, true));\n  if (best) info += kv(\"Sum of best\", fmt(best.final, true));\n  if (pb) info += kv(\"Personal best\", fmt(pb.final, true));\n  put($(\"info\"), info);\n\n\n  const note = !S.siteRuns ? \"No runs from the stats site yet, so there's nothing to compare with.\" : \"\";\n  $(\"note\").textContent = note; $(\"note\").classList.toggle(\"hide\", !note);\n}\n// every frame (for the milliseconds)\nconst frame = () => { render(); requestAnimationFrame(frame); };\nrequestAnimationFrame(frame);\n</script>\n</body>\n</html>\n";
const VERSION = "0.1";

// ---------- Settings ----------
const args = process.argv.slice(2);
const opt = name => { const i = args.indexOf("--" + name); return i >= 0 ? args[i + 1] : undefined; };
const DEFAULT_SITE = "https://zesskyo.github.io/aa-stats-no-reset-zesskyo-log/";
const SITE = opt("site") || DEFAULT_SITE;
const PORT = Number(opt("port") || 7476);
const WORLD = opt("world") ? path.resolve(opt("world")) : null;
const home = os.homedir();
// where Hermes keeps its list of running games (the same places as HermesCore.getGlobalPath)
const HERMES_GLOBAL = process.platform === "darwin" ? path.join(home, "Library", "Application Support", "MCSRHermes")
  : process.platform === "win32" ? path.join(process.env.LOCALAPPDATA || process.env.APPDATA || home, "MCSRHermes")
  : process.env.XDG_RUNTIME_DIR ? path.join(process.env.XDG_RUNTIME_DIR, "MCSRHermes") : path.join(home, ".local", "share", "MCSRHermes");
// this program's own folder: the last stats site download (for when there's no internet) and the last world
const OWN = process.platform === "darwin" ? path.join(home, "Library", "Application Support", "AA Live") : path.join(home, ".aa-live");
fs.mkdirSync(OWN, {recursive: true});
const ownFile = f => path.join(OWN, f);
const readJson = f => { try { return JSON.parse(fs.readFileSync(f, "utf8")); } catch { return null; } };
const log = (...m) => console.log(new Date().toLocaleTimeString(), ...m);

// ---------- The stats site's code and runs ----------
let site = null;   // {api, comps, icons, title, runs, fetchedAt}
function loadSite(data, fetchedAt) {
  const document = {getElementById: () => ({textContent: JSON.stringify(data)})};
  const api = new Function("document", SITE_CODE + "\nreturn {parseLog, derive, validRuns, pbRun, RUNS, runNum, WR, SPLITS, ADV, ICONS, LAST_ICON, FALLBACK_LAST_ICON, VVF, T};")(document);
  const valid = api.validRuns(), n = api.SPLITS.length, POST = n - 1;
  const durs = r => api.derive(r).splits.map((s, i) => s.dur ?? (i === POST ? 0 : null));   // (most runs have no Post-endgame)
  const all = valid.map(durs);
  const col = i => all.map(d => d[i]).filter(v => v != null);
  const pb = api.pbRun(), wr = api.WR && api.WR.finalIgt != null ? api.WR : null;
  const finals = valid.map(r => r.finalIgt);
  const comps = {
    pb: pb ? {name: "Personal Best", short: "PB", splits: durs(pb), final: pb.finalIgt} : null,
    avg: all.length ? {name: "Average", short: "Average", splits: [...Array(n)].map((_, i) => { const c = col(i); return c.length ? c.reduce((a, b) => a + b, 0) / c.length : null; }), final: finals.reduce((a, b) => a + b, 0) / finals.length} : null,
    best: all.length ? {name: "Best Segments", short: "Best", splits: [...Array(n)].map((_, i) => { const c = col(i); return c.length ? Math.min(...c) : null; })} : null,
    worst: all.length ? {name: "Worst Segments", short: "Worst", splits: [...Array(n)].map((_, i) => { const c = col(i); return c.length ? Math.max(...c) : null; }), final: Math.max(...finals)} : null,
    wr: wr ? {name: "World Record" + (wr.meta && wr.meta.runner ? " · " + wr.meta.runner : ""), short: "WR", splits: durs(wr), final: wr.finalIgt} : null,
  };
  if (comps.best) { comps.best.final = comps.best.splits.reduce((a, b) => a + (b || 0), 0); comps.best.name = "Sum of Best"; }
  // icons the page needs: the splits', and every possible last-advancement icon (for Post-endgame)
  const icons = {};
  for (const k of [...api.SPLITS.map(s => s.icon), ...Object.values(api.LAST_ICON || {}), api.FALLBACK_LAST_ICON]) if (k && api.ICONS[k]) icons[k] = api.ICONS[k];
  // the run number for a new run: one after the site's last
  const nextNum = Math.max(0, ...api.RUNS.map(r => api.runNum(r))) + 1;
  site = {api, comps, icons, nextNum, title: (data.text && data.text.siteTitle) || "AA No Reset", runs: valid.length, fetchedAt};
  log(`Stats site: ${valid.length} runs` + (pb ? `, PB ${fmt(pb.finalIgt)}` : "") + (wr ? `, WR ${fmt(wr.finalIgt)}` : ""));
}

async function fetchSite() {
  try {
    let html;
    if (/^https?:\/\//i.test(SITE)) {
      const res = await fetch(SITE.replace(/\/?$/, m => SITE.endsWith(".html") ? "" : "/"), {headers: {"cache-control": "no-cache"}});
      if (!res.ok) throw new Error("HTTP " + res.status);
      html = await res.text();
    } else html = fs.readFileSync(path.resolve(SITE.replace(/^~(?=\/)/, home)), "utf8");
    const m = /<script type="application\/json" id="aa-data">([\s\S]*?)<\/script>/.exec(html);
    if (!m) throw new Error("that page isn't a stats site (no runs in it)");
    const data = JSON.parse(m[1]);
    fs.writeFileSync(ownFile("site-cache.json"), JSON.stringify({site: SITE, fetchedAt: Date.now(), data}));
    loadSite(data, Date.now());
  } catch (e) {
    log(`Couldn't load the stats site (${e.message})`);
    if (!site) {
      const c = readJson(ownFile("site-cache.json"));
      if (c && c.site === SITE) { loadSite(c.data, c.fetchedAt); log("Using the copy from " + new Date(c.fetchedAt).toLocaleString()); }
      else loadSite({runs: []}, null);
    }
  }
  update();
}

// ---------- Finding the world ----------
// The world being played (or the last one played), from Hermes' files in the game folder
function findWorld() {
  if (WORLD) return WORLD;
  const games = new Set();
  try {
    for (const f of fs.readdirSync(path.join(HERMES_GLOBAL, "instances"))) {
      const j = f.endsWith(".json") && readJson(path.join(HERMES_GLOBAL, "instances", f));
      if (j && j.game_dir) games.add(j.game_dir);
    }
  } catch {}
  const last = readJson(ownFile("last.json")) || {};
  if (last.game) games.add(last.game);
  let best = null;
  for (const g of games) {
    const st = readJson(path.join(g, "hermes", "state.json"));
    if (!st) continue;
    const w = st.world || st.last_world_joined;
    if (!w || !w.path) continue;
    const p = w.relative ? path.join(g, w.path) : w.path;
    let t = 0; try { t = fs.statSync(path.join(g, "hermes", "state.json")).mtimeMs; } catch {}
    const score = (st.world ? 1e15 : 0) + t;   // a world that's open now beats the last one played
    if (!best || score > best.score) best = {p, g, score};
  }
  if (best) { if (best.g !== last.game || best.p !== last.world) fs.writeFileSync(ownFile("last.json"), JSON.stringify({game: best.g, world: best.p})); return best.p; }
  return last.world || null;
}

// ---------- Following the play log ----------
let world = null, file = null, offset = 0, rest = Buffer.alloc(0), text = "", plain = false;
let anchor = null;      // {igt, wall}: the IGT at the latest line, and when that was
let paused = true, open = false, changed = false;

function reset(w) {
  world = w; file = null; offset = 0; rest = Buffer.alloc(0); text = ""; anchor = null; paused = true; open = false; changed = true;
  log(w ? "World: " + w : "Waiting for Minecraft (Hermes)…");
}

function readNew() {
  const w = findWorld();
  if (w !== world) reset(w);
  if (!world) return;
  const enc = path.join(world, "hermes", "restricted", "play.log.enc"), dec = path.join(world, "hermes", "play.log");
  const f = fs.existsSync(enc) ? enc : fs.existsSync(dec) ? dec : null;
  if (!f) return;
  if (f !== file) { file = f; plain = f === dec; offset = 0; rest = Buffer.alloc(0); text = ""; }
  let size; try { size = fs.statSync(f).size; } catch { return; }
  if (size < offset) { offset = 0; rest = Buffer.alloc(0); text = ""; }   // (started again)
  if (size === offset) return;
  const fd = fs.openSync(f, "r"), chunk = Buffer.alloc(size - offset);
  try { fs.readSync(fd, chunk, 0, chunk.length, offset); } finally { fs.closeSync(fd); }
  offset = size;
  const buf = Buffer.concat([rest, chunk]), end = buf.lastIndexOf(10);
  if (end < 0) { rest = buf; return; }
  rest = Buffer.from(buf.subarray(end + 1));
  const lines = buf.subarray(0, end + 1);
  if (!plain) { let s = 0; for (let i = 0; i < lines.length; i++) if (lines[i] === 10) { rotate(lines.subarray(s, i)); s = i + 1; } }
  // times are SpeedRunIGT's retimed IGT ("retime"; the IGT rounded to game ticks): put it where "igt" is, so the
  // timer and the stats site's log reader (which read "igt") both use it
  const t = lines.toString("utf8").replace(/"igt":\d+,"retime":(\d+)/g, '"igt":$1,"retime":$1');
  text += t;
  for (const line of t.split("\n")) watchLine(line);
  changed = true;
}

// What the timer needs, from each line (cheaply): the IGT, whether the world is open, and whether the game is paused
function watchLine(line) {
  if (!line.startsWith('{"time":')) return;
  const wall = parseInt(line.slice(8), 10), gi = line.lastIndexOf('"igt":');
  const q = line.indexOf('"type":"'), type = q > 0 ? line.slice(q + 8, line.indexOf('"', q + 8)) : "";
  if (gi > 0) { const igt = parseInt(line.slice(gi + 6), 10); if (!anchor || igt >= anchor.igt) anchor = {igt, wall}; }
  if (type === "initialize") { open = true; paused = false; }
  else if (type === "close" || type === "server_shutdown") { open = false; paused = true; }
  else if (type === "screen") paused = line.includes('"is_pause":true');
}

// ---------- The splits ----------
let state = null;
function update() {
  if (!site) return;
  state = compute();
  const msg = "data: " + JSON.stringify(state) + "\n\n";
  for (const c of clients) c.write(msg);
}

function compute() {
  const {api} = site, n = api.SPLITS.length;
  const base = {v: VERSION, title: site.title, siteRuns: site.runs, siteAt: site.fetchedAt, comps: site.comps, icons: site.icons,
    world: world ? path.basename(world) : null, file: !!file, open, paused, anchor, now: Date.now()};
  const empty = {...base, num: site.nextNum, done: false, thunderless: false, igt: anchor ? anchor.igt : 0,
    splits: api.SPLITS.map((s, i) => ({name: s.name, icon: s.icon || api.FALLBACK_LAST_ICON, dur: 0, from: i === 0 ? 0 : null, has: false}))};
  if (!text) return empty;
  let run;
  try { run = api.parseLog(text, "play.log"); } catch { return empty; }
  // finished: everything done, or everything but Very Very Frightening (Thunderless; if thunder still comes, it carries on)
  const missing = api.derive(run).missing, done0 = !missing.length || (missing.length === 1 && missing[0] === api.VVF);
  const now = anchor ? Math.max(anchor.igt, run.finalIgt) : run.finalIgt;
  if (!done0) {
    // Still going: the run so far, as if it ended now (and as if back in the Overworld now, so a split that ends on
    // getting back there is shown as running)
    delete run._d;
    run.finalIgt = now;
    run.dims.push([now, "o"]);
  }
  const d = api.derive(run);
  const end = done0 ? run.finalIgt : now;
  // each split: its time so far, and when it's running, where the running part started
  const rows = d.splits.map((s, i) => {
    const segs = s.segs.filter(g => g[1] > g[0]);
    const last = segs[segs.length - 1], running = !done0 && last && last[1] === end;
    const dur = segs.reduce((a, g) => a + g[1] - g[0], 0);
    return {name: s.name, icon: s.icon, has: segs.length > 0, dur: running ? dur - (last[1] - last[0]) : dur, from: running ? last[0] : null, end: segs.length ? last[1] : null};
  });
  // nothing running yet (e.g. still in Any%, or between splits): the first split with nothing in it, from the end of the one before
  if (!done0 && !rows.some(r => r.from != null)) {
    const i = rows.findIndex(r => !r.has);
    if (i >= 0) rows[i].from = i === 0 ? 0 : Math.max(0, ...rows.slice(0, i).filter(r => r.end != null).map(r => r.end));
  }
  // its run number: the site's, if it's already on the site (looking at an old world), or the next one
  const known = api.RUNS.find(r => r.start === run.start && r.player === run.player);
  const num = known ? api.runNum(known) : site.nextNum;
  return {...base, num, done: done0, thunderless: done0 && missing.length === 1, igt: end, splits: rows.map(({end, ...r}) => r)};
}

// ---------- The page ----------
const clients = new Set();
const server = http.createServer((req, res) => {
  const url = new URL(req.url, "http://x");
  if (url.pathname === "/events") {
    res.writeHead(200, {"content-type": "text/event-stream", "cache-control": "no-cache", connection: "keep-alive", "access-control-allow-origin": "*"});
    res.write("retry: 1000\n\n");
    if (state) res.write("data: " + JSON.stringify(state) + "\n\n");
    clients.add(res);
    req.on("close", () => clients.delete(res));
  } else if (url.pathname === "/state.json") {
    res.writeHead(200, {"content-type": "application/json"}); res.end(JSON.stringify(state));
  } else if (url.pathname === "/") {
    res.writeHead(200, {"content-type": "text/html; charset=utf-8", "cache-control": "no-cache"}); res.end(PAGE);
  } else { res.writeHead(404); res.end(); }
});
server.on("error", e => { console.error(e.code === "EADDRINUSE" ? `Port ${PORT} is in use (is AA Live already running?). Use --port to pick another.` : e.message); process.exit(1); });
server.listen(PORT, "127.0.0.1", () => {
  const link = `http://localhost:${PORT}/`;
  console.log(`\nAA Live ${VERSION}\n  Splits (and the OBS browser source): ${link}\n  Stats site:    ${SITE}\n`);
  if (!args.includes("--no-open") && process.platform === "darwin") execFile("open", [link], () => {});
});

// ---------- Running ----------
const fmt = ms => { const s = Math.floor(ms / 1000); return `${Math.floor(s / 3600)}:${String(Math.floor(s / 60) % 60).padStart(2, "0")}:${String(s % 60).padStart(2, "0")}`; };
reset(null);
fetchSite();
setInterval(fetchSite, 30 * 60000);
let lastParse = 0;
setInterval(() => {
  try { readNew(); } catch (e) { log("Couldn't read the play log: " + e.message); }
  // the splits are worked out again at most once a second (the whole log is read each time)
  if (changed && Date.now() - lastParse >= 1000) { changed = false; lastParse = Date.now(); update(); }
}, 250);
// keep OBS's connection alive
setInterval(() => { for (const c of clients) c.write(": .\n\n"); }, 15000);
